// The Play build of the DEEP DOWN shell: compileSdk/targetSdk 36, minSdk 24, no AndroidX, no
// minify. Unverified until its first CI run (see android/README.md).
//
// - Version: tools/version.mjs (package.json "version" + DD_BUILD), the same rule as the game
//   and android/build-apk.sh.
// - Web assets: a stale-checked copy of ../dist (built with DD_RELEASE=1 before Gradle runs).
// - Icons and splash logo: generated by ../make-icon.mjs.
// - Signing: the upload key comes from the environment only (DD_UPLOAD_*), never from a file in
//   the repository. Without it, release outputs are unsigned.
// - src/modern: the manifest overlay and values-v31 theme that need a current SDK to link.
import javax.inject.Inject

plugins {
    id("com.android.application")
}

val repoRoot: File = rootDir.parentFile

/** {"version":"1.0.0","build":0,"versionCode":1000000} from tools/version.mjs (inherits DD_BUILD). */
val versionJson: String = providers.exec {
    commandLine("node", File(repoRoot, "tools/version.mjs").path)
}.standardOutput.asText.get()
val ddVersionName: String = Regex("\"version\":\"([^\"]+)\"").find(versionJson)?.groupValues?.get(1)
    ?: error("tools/version.mjs printed no version: $versionJson")
val ddVersionCode: Int = Regex("\"versionCode\":(\\d+)").find(versionJson)?.groupValues?.get(1)?.toInt()
    ?: error("tools/version.mjs printed no versionCode: $versionJson")

val uploadStore: String? = System.getenv("DD_UPLOAD_STORE_FILE")?.takeIf { it.isNotBlank() }

android {
    namespace = "com.korroai.deepdown"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.korroai.deepdown"
        minSdk = 24
        targetSdk = 36
        versionCode = ddVersionCode
        versionName = ddVersionName
    }

    signingConfigs {
        create("release") {
            if (uploadStore != null) {
                storeFile = file(uploadStore)
                storePassword = System.getenv("DD_UPLOAD_STORE_PASSWORD")
                keyAlias = System.getenv("DD_UPLOAD_KEY_ALIAS")
                keyPassword = System.getenv("DD_UPLOAD_KEY_PASSWORD")
            }
        }
    }

    buildTypes {
        getByName("release") {
            isMinifyEnabled = false
            isShrinkResources = false
            signingConfig = if (uploadStore != null) signingConfigs.getByName("release") else null
        }
    }

    sourceSets {
        getByName("main") {
            res.srcDirs("src/main/res", "src/modern/res")
        }
        // The overlay is merged over src/main/AndroidManifest.xml for both build types.
        getByName("debug") { manifest.srcFile("src/modern/AndroidManifest.xml") }
        getByName("release") { manifest.srcFile("src/modern/AndroidManifest.xml") }
    }

    compileOptions {
        // Same language level as build-apk.sh (javac --release 8, dx): no lambdas in the shell.
        sourceCompatibility = JavaVersion.VERSION_1_8
        targetCompatibility = JavaVersion.VERSION_1_8
    }
}

/** Copy ../dist into the variant's assets as www/, refusing a stale, partial or non-release build. */
abstract class WebAssetsTask : DefaultTask() {
    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val dist: DirectoryProperty

    @get:Input
    abstract val versionCode: Property<Int>

    @get:Input
    abstract val requireRelease: Property<Boolean>

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val fs: FileSystemOperations

    @TaskAction
    fun copy() {
        val root = dist.get().asFile
        val index = File(root, "index.html")
        check(index.isFile) { "$index is missing: run `DD_RELEASE=1 npx vite build` in deep-down/ first" }
        val refs = Regex("(?:src|href)=\"\\./(assets/[^\"]+)\"").findAll(index.readText()).map { it.groupValues[1] }.toList()
        check(refs.isNotEmpty()) { "dist/index.html references no bundled assets (placeholder build?)" }
        for (ref in refs) check(File(root, ref).isFile) { "dist is stale: missing $ref" }
        val worker = File(root, "assets").listFiles()?.any { it.name.startsWith("slabWorker-") && it.name.endsWith(".js") } ?: false
        check(worker) { "dist is missing the world-generation worker" }
        val stamp = File(root, "version.json")
        check(stamp.isFile) { "dist/version.json is missing: dist predates the release pipeline, rebuild it" }
        val stampText = stamp.readText()
        val built = Regex("\"versionCode\":(\\d+)").find(stampText)?.groupValues?.get(1)?.toInt()
        check(built == versionCode.get()) { "dist is stale: built for versionCode $built, packaging ${versionCode.get()} (same DD_BUILD for both steps?)" }
        if (requireRelease.get()) {
            check(stampText.contains("\"release\":true")) { "a release bundle needs a DD_RELEASE=1 web build" }
            check(!File(root, "visuallab.html").exists()) { "a release bundle must not contain the Visual Lab" }
        }
        val out = outputDir.get().asFile
        fs.sync {
            from(root)
            into(File(out, "www"))
        }
    }
}

/** Launcher icons (legacy + adaptive layers + monochrome) and the splash logo, per density. */
abstract class IconsTask : DefaultTask() {
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val scripts: ConfigurableFileCollection

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val execOps: ExecOperations

    @TaskAction
    fun generate() {
        val out = outputDir.get().asFile
        out.deleteRecursively()
        out.mkdirs()
        execOps.exec {
            commandLine("node", scripts.files.first { it.name == "make-icon.mjs" }.path, out.path)
        }
    }
}

androidComponents {
    onVariants { variant ->
        val cap = variant.name.replaceFirstChar { it.uppercase() }
        val web = tasks.register<WebAssetsTask>("copyWeb$cap") {
            dist.set(File(repoRoot, "dist"))
            versionCode.set(ddVersionCode)
            requireRelease.set(variant.buildType == "release")
        }
        variant.sources.assets?.addGeneratedSourceDirectory(web, WebAssetsTask::outputDir)
        val icons = tasks.register<IconsTask>("generateIcons$cap") {
            scripts.from(File(rootDir, "make-icon.mjs"), File(repoRoot, "tools/png.mjs"))
        }
        variant.sources.res?.addGeneratedSourceDirectory(icons, IconsTask::outputDir)
    }
}
